class RangeModule:

    def __init__(self):
        # Store intervals as a sorted list of [start, end)
        self.intervals = []

    def addRange(self, left: int, right: int) -> None:
        res = []
        placed = False
        for l, r in self.intervals:
            if r < left:
                res.append([l, r])
            elif right < l:
                if not placed:
                    res.append([left, right])
                    placed = True
                res.append([l, r])
            else:
                # Overlapping intervals; merge
                left = min(left, l)
                right = max(right, r)
        if not placed:
            res.append([left, right])
        self.intervals = res

    def queryRange(self, left: int, right: int) -> bool:
        # Binary search to find if [left, right) is fully inside some [l, r)
        from bisect import bisect_right
        idx = bisect_right(self.intervals, [left, float('inf')])
        if idx == 0:
            return False
        l, r = self.intervals[idx-1]
        return l <= left and right <= r

    def removeRange(self, left: int, right: int) -> None:
        res = []
        for l, r in self.intervals:
            if r <= left or l >= right:
                res.append([l, r])
            else:
                # Non-trivial removal, may need to split
                if l < left:
                    res.append([l, left])
                if r > right:
                    res.append([right, r])
        self.intervals = res
